<script setup lang="ts">
import {ref,onMounted} from 'vue';
import type {Grant,Page} from '@survey/shared';
import {api} from '../api';
import {queryPage} from '../library-client';
const props=defineProps<{questionId:string;revision:number;disabled?:boolean}>(),emit=defineEmits<{changed:[]}>(),rows=ref<Grant[]>([]),cursor=ref<string|null>(null),username=ref(''),busy=ref(false),error=ref(''),notice=ref('');
async function load(more=false){busy.value=true;error.value='';try{const page=await api<Page<Grant>>(`/questions/${props.questionId}/shares`+queryPage({limit:'20',cursor:more?cursor.value??undefined:undefined}));rows.value=more?[...rows.value,...page.items]:page.items;cursor.value=page.nextCursor;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function change(g:Grant|null,revoke=false){if(props.disabled)return;busy.value=true;error.value='';notice.value='';try{await api(`/questions/${props.questionId}/shares${revoke?`/${g!.id}/revocation`:''}`,revoke?'POST':'PUT',{expectedRevision:props.revision,expectedGrantRevision:g?.revision??null,...(revoke?{}:{username:g?.recipientUsername??username.value})});emit('changed');await load();notice.value=revoke?'共享已撤销；对方已保存实例仍可使用原版。':'共享已生效，包含全部正式历史及未来版本，不包含编辑草稿。';}catch(e){error.value=(e as Error).message;emit('changed');}finally{busy.value=false;}}
onMounted(()=>load());
</script>
<template><section class="panel"><h2>指定用户共享</h2><p class="muted">只向已注册用户名共享题目。撤销后禁止新增引用与派生，已保存实例继续使用原版。</p><p v-if="error" class="error" role="alert">{{error}} <button class="quiet" @click="load()">刷新授权列表</button></p><p v-if="notice" class="saved" role="status">{{notice}}</p><form @submit.prevent="change(rows.find(g=>g.recipientUsername.toLowerCase()===username.trim().toLowerCase())??null)"><label for="share-username">注册用户名</label><input id="share-username" v-model="username" :disabled="disabled||busy" autocomplete="off"><button class="secondary" :disabled="disabled||busy||!username.trim()">授予共享</button></form><p v-if="!rows.length&&!busy">尚未授予共享。</p><ul class="library-rows"><li v-for="g in rows" :key="g.id"><span>{{g.recipientUsername}} · {{g.state==='active'?'共享中':'已撤销'}}</span><button class="quiet" :disabled="disabled||busy" @click="change(g,g.state==='active')">{{g.state==='active'?'撤销共享':'重新授予'}}</button></li></ul><button v-if="cursor" class="secondary" :disabled="disabled||busy" @click="load(true)">更多授权</button></section></template>
